[
  {
    "name": "count_1_0",
    "request": {
      "command": "count",
      "protocol": "1",
      "receipts": []
    },
    "expected": {
      "protocol": "1",
      "accepted_count": 0,
      "duplicate_count": 0
    }
  },
  {
    "name": "count_1_1",
    "request": {
      "command": "count",
      "protocol": "1",
      "receipts": [
        {
          "record_id": "R-1",
          "account_id": "A",
          "delivery_id": "D-1",
          "occurred_at": "2026-04-01T10:00:00Z",
          "payload": "payload:R-1"
        }
      ]
    },
    "expected": {
      "protocol": "1",
      "accepted_count": 1,
      "duplicate_count": 0
    }
  }
]

